		\path (0, 0)			node[result]	(theo2)		{Proposition \ref{prop: relative compactness of occupancy state sample paths}\\ \scriptsize{Relative compactness of occupancy processes}}
		+(1, 0)			node[result]	(coro1)		{Corollary \ref{cor: decay of the tail}\\ \scriptsize{Proof of \eqref{seq: main result 3}}}
