		+(1,-2)			node[result]	(lemm6)		{Lemmas \ref{lem: lemma 1 for main result} and \ref{lem: lemma 2 for main result}\\ \scriptsize{Leveraging refined strong approximations}}
		+(0,-3)			node[result]	(prop5)		{Proposition \ref{prop: tail number of tasks}\\ \scriptsize{Asymptotic dynamical properties of tail mass}}
		+(2,-3)			node[result]	(prop4)		{Proposition \ref{prop: total number of tasks}\\ \scriptsize{Asymptotic dynamical properties of total mass}}
		+(1,-4)			node[result]	(prop3)		{Proposition \ref{prop: definition of Omega_T}\\ \scriptsize{Nice sample paths (refined strong approximations)}}
		+(-0.48,0.45)	node[anchor = south west]	{Section \ref{sub: relative compactness exponential case}}
		+(0.52,0.45)	node[anchor = south west]	{Section \ref{sub: evolution of the threshold}}
		+(-0.48,-2.55)	node[anchor = south west]	{Section \ref{sub: asymptotic dynamical properties exponential case}};
		
		\draw[thick]	(theo2)		--		(prop5);
		\draw[arrow]	(0,-1)		--		(theo1);
		\draw[arrow]	(0.5,-1)	|-		(coro1);
		\draw[arrow]	(coro1)		--		(theo1);
		\draw[arrow]	(prop6)		|-		(coro1);
		\draw[arrow]	(lemm6)		--		(theo1);
		\draw[arrow]	(prop3)		-|		(prop5);
		\draw[arrow]	(prop3)		--		(lemm6);
		\draw[arrow]	(prop4)		--		(prop6);
		\draw[arrow]	(prop3)		-|		(prop4);
		\draw[arrow]	(prop6)		--		(theo1);
		
		\draw[dotted, thick]	(-0.45,0.45)	rectangle	(0.45,-0.45);
		\draw[dotted, thick]	(0.55, 0.45)	rectangle	(2.45,-2.45);
		\draw[dotted, thick]	(-0.45, -2.55)	rectangle	(2.45,-4.45);
		
	\end{tikzpicture}
	\caption{Schematic representation of the relations between the various results used to prove Theorem~\ref{the: main theorem exponential case}; some intermediate results are omitted. An arrow connecting two results means that the first result is used to prove the second. The dotted boxes indicate the sections where the results are proven.}
	\label{fig: proof diagram}
\end{figure}

